// Cross-language reader for the research-only Julia report fixture.
// JSON is generated by scripts/p2-selection-count-report-io-check.jl and is
// never imported by the production entry or public lesson catalog.
import reportFixture from "../../validation/p2-likelihood/fixtures/selection-count-report-v1.json";

export const REPORT_SCHEMA_ID = "learning-julia.p2.selection-count-report";
export const REPORT_SCHEMA_VERSION = "1.0.0";

const REPORT_STATUSES = new Set([
  "review_profile_and_bootstrap",
  "unresolved_profile",
  "unresolved_bootstrap",
]);
const METHOD_NAMES = new Set(["wald", "profile", "bootstrap"]);
const METHOD_STATUSES = new Set([
  "ok",
  "search_limit",
  "skipped_weak_identification",
  "error",
  "insufficient_success",
]);
const MESSAGE_CODES = new Set([
  "wald_is_local_approximation",
  "profile_interval_unresolved",
  "profile_skipped_weak_identification",
  "profile_computation_error",
  "bootstrap_success_rate_too_low",
  "compare_profile_and_bootstrap",
]);

const fail = (message) => {
  throw new Error(`P2 report schema error: ${message}`);
};

function exactKeys(value, expected, label) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    fail(`${label}はobjectである必要があります`);
  }
  const actual = Object.keys(value).sort();
  const wanted = [...expected].sort();
  if (actual.length !== wanted.length || actual.some((key, index) => key !== wanted[index])) {
    fail(`${label}のkeyが一致しません: ${actual.join(",")}`);
  }
}

const isFiniteNumber = (value) => typeof value === "number" && Number.isFinite(value);

function validateInterval(interval, methodStatus) {
  exactKeys(interval, ["parameter", "lower", "upper"], "interval");
  if (!new Set(["mu", "sigma"]).has(interval.parameter)) fail("parameterが不正です");
  if (methodStatus === "ok") {
    if (!isFiniteNumber(interval.lower) || !isFiniteNumber(interval.upper) || interval.lower >= interval.upper) {
      fail("ok methodの区間端点が不正です");
    }
    if (interval.parameter === "sigma" && interval.lower <= 0) fail("sigma区間は正にしてください");
  } else if (interval.lower !== null || interval.upper !== null) {
    fail("未解決methodの区間端点はnullにしてください");
  }
}

function validateDiagnostics(diagnostics, method) {
  if (method.method !== "bootstrap") {
    if (diagnostics !== null) fail("bootstrap以外のdiagnosticsはnullにしてください");
    return;
  }
  exactKeys(
    diagnostics,
    ["total_screened", "repetitions", "successes", "success_rate", "minimum_success_rate"],
    "bootstrap diagnostics"
  );
  const { total_screened: total, repetitions, successes, success_rate: rate, minimum_success_rate: minimum } = diagnostics;
  if (!Number.isInteger(total) || total < 2) fail("bootstrap total_screenedが不正です");
  if (!Number.isInteger(repetitions) || repetitions < 1) fail("bootstrap repetitionsが不正です");
  if (!Number.isInteger(successes) || successes < 0 || successes > repetitions) fail("bootstrap successesが不正です");
  if (!isFiniteNumber(rate) || rate < 0 || rate > 1) fail("bootstrap success_rateが不正です");
  if (Math.abs(rate - successes / repetitions) > 1e-12) fail("bootstrap成功数と成功率が一致しません");
  if (!isFiniteNumber(minimum) || minimum <= 0 || minimum > 1) fail("bootstrap minimum_success_rateが不正です");
  const expected = rate >= minimum ? "ok" : "insufficient_success";
  if (method.status !== expected) fail("bootstrap statusと成功率が一致しません");
}

function validateMethod(method) {
  exactKeys(method, ["method", "status", "intervals", "diagnostics"], "method");
  if (!METHOD_NAMES.has(method.method)) fail(`未登録method: ${method.method}`);
  if (!METHOD_STATUSES.has(method.status)) fail(`未登録method status: ${method.status}`);
  if (method.method === "wald" && method.status !== "ok") fail("Wald statusはokにしてください");
  if (method.method === "profile" && method.status === "insufficient_success") fail("profile statusが不正です");
  if (method.method === "bootstrap" && !new Set(["ok", "insufficient_success"]).has(method.status)) {
    fail("bootstrap statusが不正です");
  }
  if (!Array.isArray(method.intervals) || method.intervals.length !== 2) fail("methodには2区間が必要です");
  if (new Set(method.intervals.map((interval) => interval.parameter)).size !== 2) fail("mu・sigmaが重複しています");
  method.intervals.forEach((interval) => validateInterval(interval, method.status));
  validateDiagnostics(method.diagnostics, method);
}

function validateReport(report) {
  exactKeys(
    report,
    ["report_id", "status", "automatic_interval", "input_contract", "methods", "messages"],
    "report"
  );
  if (typeof report.report_id !== "string" || report.report_id.length === 0) fail("report_idが空です");
  if (!REPORT_STATUSES.has(report.status)) fail(`未登録report status: ${report.status}`);
  if (report.automatic_interval !== null) fail("automatic_intervalはnullのままにしてください");
  exactKeys(
    report.input_contract,
    ["total_screened", "selected_count", "lower_boundary", "upper_boundary", "boundary_rule"],
    "input_contract"
  );
  const input = report.input_contract;
  if (!Number.isInteger(input.total_screened) || input.total_screened < 2) fail("total_screenedが不正です");
  if (!Number.isInteger(input.selected_count) || input.selected_count < 2 || input.selected_count > input.total_screened) {
    fail("selected_countが不正です");
  }
  if (!isFiniteNumber(input.lower_boundary) || !isFiniteNumber(input.upper_boundary) || input.lower_boundary >= input.upper_boundary) {
    fail("境界が不正です");
  }
  if (input.boundary_rule !== "lower < value < upper") fail("boundary_ruleが不正です");
  if (!Array.isArray(report.methods) || report.methods.length !== 3) fail("3 methodが必要です");
  report.methods.forEach(validateMethod);
  const methods = new Map(report.methods.map((method) => [method.method, method]));
  if (methods.size !== 3 || [...METHOD_NAMES].some((name) => !methods.has(name))) fail("methodが欠落または重複しています");
  const expectedStatus = methods.get("profile").status !== "ok"
    ? "unresolved_profile"
    : methods.get("bootstrap").status !== "ok"
      ? "unresolved_bootstrap"
      : "review_profile_and_bootstrap";
  if (report.status !== expectedStatus) fail("report statusとmethod statusが一致しません");
  if (!Array.isArray(report.messages) || report.messages.length === 0) fail("message codeがありません");
  if (report.messages.some((message) => !MESSAGE_CODES.has(message))) fail("未登録message codeがあります");
  if (!report.messages.includes("wald_is_local_approximation")) fail("Waldの局所近似messageがありません");
  if (report.status === "unresolved_profile" && !report.messages.some((message) => message.startsWith("profile_"))) {
    fail("profile未解決messageがありません");
  }
  if (report.status === "unresolved_bootstrap" && !report.messages.includes("bootstrap_success_rate_too_low")) {
    fail("bootstrap未解決messageがありません");
  }
  if (report.status === "review_profile_and_bootstrap" && !report.messages.includes("compare_profile_and_bootstrap")) {
    fail("method比較messageがありません");
  }
}

export function validateSelectionCountReportBundle(bundle) {
  exactKeys(bundle, ["schema_id", "schema_version", "model_scope", "reports"], "bundle");
  if (bundle.schema_id !== REPORT_SCHEMA_ID) fail("schema_idが不正です");
  if (bundle.schema_version !== REPORT_SCHEMA_VERSION) fail("未対応schema_versionです");
  exactKeys(bundle.model_scope, ["family", "selection_rule", "automatic_interval_selection"], "model_scope");
  if (bundle.model_scope.family !== "Normal") fail("Normal専用schemaです");
  if (bundle.model_scope.selection_rule !== "strict_open_interval") fail("selection_ruleが不正です");
  if (bundle.model_scope.automatic_interval_selection !== false) fail("automatic interval selectionを有効化できません");
  if (!Array.isArray(bundle.reports) || bundle.reports.length === 0) fail("reportがありません");
  bundle.reports.forEach(validateReport);
  if (new Set(bundle.reports.map((report) => report.report_id)).size !== bundle.reports.length) fail("report_idが重複しています");
  return true;
}

const intervalByParameter = (method) => Object.fromEntries(
  method.intervals.map((interval) => [
    interval.parameter,
    interval.lower === null ? null : [interval.lower, interval.upper],
  ])
);

export function toWebIntervalReports(bundle) {
  validateSelectionCountReportBundle(bundle);
  return Object.fromEntries(bundle.reports.map((report) => {
    const methods = Object.fromEntries(report.methods.map((method) => {
      const intervals = intervalByParameter(method);
      return [method.method, {
        status: method.status,
        mu: intervals.mu,
        sigma: intervals.sigma,
        ...(method.diagnostics ? {
          totalScreened: method.diagnostics.total_screened,
          repetitions: method.diagnostics.repetitions,
          successes: method.diagnostics.successes,
          successRate: method.diagnostics.success_rate,
          minimumSuccessRate: method.diagnostics.minimum_success_rate,
        } : {}),
      }];
    }));
    return [report.report_id, {
      schemaVersion: bundle.schema_version,
      status: report.status,
      automaticInterval: report.automatic_interval,
      inputContract: {
        totalScreened: report.input_contract.total_screened,
        selectedCount: report.input_contract.selected_count,
        lowerBoundary: report.input_contract.lower_boundary,
        upperBoundary: report.input_contract.upper_boundary,
      },
      messages: [...report.messages],
      methods,
    }];
  }));
}

function deepFreeze(value) {
  if (value && typeof value === "object" && !Object.isFrozen(value)) {
    Object.freeze(value);
    Object.values(value).forEach(deepFreeze);
  }
  return value;
}

export const SELECTION_COUNT_REPORT_FIXTURE = deepFreeze(reportFixture);
export const INTERVAL_REPORTS = deepFreeze(toWebIntervalReports(SELECTION_COUNT_REPORT_FIXTURE));
